  font-size: 0.8125rem;
  color: #5b6472;
}

.status {
  text-transform: uppercase;
  border-radius: 999px;
  padding: 0.0625rem 0.5rem;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.03em;
}

.statusDraft {
  background: #edf0f5;
  color: #5b6472;
}

.statusPublished {
  background: #e4f5ea;
  color: #1c7a41;
}

