1	<!--
2	  Wireframe Kit (low fidelity) — a project-agnostic breadboard UI vocabulary
3	  ==========================================================================
4	  A self-contained, theme-aware template for low-fidelity wireframes of any
5	  client app — mobile OR web/desktop. It carries grey breadboard primitives, a
6	  component library, two device canvases (a mobile phone frame and a browser
7	  window), screen archetypes for both, and an options-comparison layout.
8	  Regions, hierarchy, and flow only — no brand color, no final type.
9	  Copy this file to a scratch location, delete the parts you are not presenting,
10	  fill it for the screen(s) at hand, and publish/export it. See the wireframe-design skill.
11	  Self-contained: no external fetches; system font stacks only.
12	  Fill-in points are marked with "FILL:" comments throughout.
13	-->
14	<title>Wireframe Kit — breadboard UI</title>
15	<style>
16	  /* =========================================================================
17	     PAGE CHROME (theme-aware) — the surface the mockups sit on.
18	     This is general page craft, NOT the mocked app's tokens. Keep it neutral
19	     so the device mockups read as the subject. The breadboard greys below are
20	     deliberately colorless — the wireframe shows regions, not brand.
21	     ========================================================================= */
22	  :root {
23	    --ground: #f4f5f7;
24	    --panel: #ffffff;
25	    --ink: #1c2024;
26	    --ink-soft: #60646c;
27	    --line: #d9d9e0;
28	    --accent: #0588f0;
29	    --danger: #dc3e42;
30	    --anno: #8e4ec6; /* annotation layer — reserved; distinct from accent & danger */
31	    --radius: 14px;
32	    --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
33	    --sans: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
34	
35	    /* Breadboard greys — WIREFRAME MODE only. Deliberately colorless. */
36	    --wire-fill: #e7e8ec;
37	    --wire-fill-2: #dfe1e6;
38	    --wire-line: #b9bcc4;
39	    --wire-ink: #7a7f88;
40	    --wire-solid: #c3c6cd;
41	  }
42	  @media (prefers-color-scheme: dark) {
43	    :root {
44	      --ground: #0e0f11; --panel: #17181b; --ink: #edeef0; --ink-soft: #b0b4ba;
45	      --line: #2c2e33; --accent: #3b9eff; --danger: #ec5d5e; --anno: #bf7af0;
46	      --wire-fill: #232529; --wire-fill-2: #2a2c31; --wire-line: #43464d;
47	      --wire-ink: #8b8f98; --wire-solid: #3a3d43;
48	    }
49	  }
50	  /* A host may stamp data-theme on <html> when the viewer toggles the theme
51	     (e.g. the Claude Code Artifact sandbox); these overrides must win in both directions. */
52	  :root[data-theme="light"] {
53	    --ground: #f4f5f7; --panel: #ffffff; --ink: #1c2024; --ink-soft: #60646c;
54	    --line: #d9d9e0; --accent: #0588f0; --danger: #dc3e42; --anno: #8e4ec6;
55	    --wire-fill: #e7e8ec; --wire-fill-2: #dfe1e6; --wire-line: #b9bcc4;
56	    --wire-ink: #7a7f88; --wire-solid: #c3c6cd;
57	  }
58	  :root[data-theme="dark"] {
59	    --ground: #0e0f11; --panel: #17181b; --ink: #edeef0; --ink-soft: #b0b4ba;
60	    --line: #2c2e33; --accent: #3b9eff; --danger: #ec5d5e; --anno: #bf7af0;
61	    --wire-fill: #232529; --wire-fill-2: #2a2c31; --wire-line: #43464d;
62	    --wire-ink: #8b8f98; --wire-solid: #3a3d43;
63	  }
64	
65	  * { box-sizing: border-box; }
66	  body { margin: 0; background: var(--ground); color: var(--ink); font-family: var(--sans); line-height: 1.55; -webkit-font-smoothing: antialiased; }
67	  .wrap { max-width: 1180px; margin: 0 auto; padding: 44px 24px 80px; }
68	  a { color: var(--accent); }
69	
70	  header.masthead { margin-bottom: 8px; }
71	  .eyebrow { font-family: var(--mono); font-size: 12px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--accent); margin: 0 0 12px; }
72	  h1 { font-size: clamp(26px, 3.4vw, 38px); line-height: 1.1; margin: 0 0 14px; letter-spacing: -0.02em; text-wrap: balance; }
73	  .lede { max-width: 64ch; color: var(--ink-soft); font-size: 16px; margin: 0; }
74	  .meta { display: flex; flex-wrap: wrap; gap: 8px 10px; margin-top: 18px; font-family: var(--mono); font-size: 12px; }
75	  .tag { border: 1px solid var(--line); border-radius: 999px; padding: 4px 11px; color: var(--ink-soft); background: var(--panel); }
76	  .tag strong { color: var(--ink); font-weight: 600; }
77	
78	  h2.section { font-size: 13px; font-family: var(--mono); text-transform: uppercase; letter-spacing: 0.12em; color: var(--ink-soft); margin: 56px 0 20px; padding-bottom: 10px; border-bottom: 1px solid var(--line); }
79	  .lead-note { max-width: 66ch; color: var(--ink-soft); font-size: 14.5px; margin: -6px 0 22px; }
80	  .lead-note code { font-family: var(--mono); font-size: 12.5px; background: var(--panel); border: 1px solid var(--line); border-radius: 5px; padding: 1px 6px; }
81	
82	  .grid-shared { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 230px), 1fr)); gap: 20px; }
83	  .grid-options { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 300px), 1fr)); gap: 22px; }
84	
85	  .card { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 20px; display: flex; flex-direction: column; gap: 16px; }
86	  /* .card.rec highlights the (Recommended) option in an options round. */
87	  .card.rec { border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent); }
88	  .card-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; }
89	  .card-head h3 { margin: 0; font-size: 17px; letter-spacing: -0.01em; }
90	  .card-head .opt { font-family: var(--mono); font-size: 11px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--ink-soft); }
91	  .badge { font-family: var(--mono); font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase; color: #fff; background: var(--accent); border-radius: 999px; padding: 3px 9px; white-space: nowrap; }
92	  .shared-label { font-family: var(--mono); font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-soft); margin: 0; }
93	  .note { margin: 0; font-size: 14px; color: var(--ink-soft); }
94	  .note b { color: var(--ink); font-weight: 600; }
95	  .note code { font-family: var(--mono); font-size: 12px; }
96	  /* Rationale / Trade-offs / Responsive labels for each option. */
97	  .note.rationale::before { content: "Rationale"; display: block; font-family: var(--mono); font-size: 10px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--wire-ink); margin-bottom: 3px; }
98	  .note.tradeoff::before { content: "Trade-offs"; display: block; font-family: var(--mono); font-size: 10px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--wire-ink); margin-bottom: 3px; }
99	  .note.responsive::before { content: "Responsive"; display: block; font-family: var(--mono); font-size: 10px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--wire-ink); margin-bottom: 3px; }
100	  .caption { text-align: center; font-family: var(--mono); font-size: 10.5px; color: var(--wire-ink); letter-spacing: 0.04em; margin: 2px 0 0; }
101	  /* =========================================================================
102	     WIREFRAME MODE — grey breadboard phone + primitives.
103	     A wireframe shows places, affordances, and flow — regions and their
104	     arrangement — not fonts, exact spacing, or final copy.
105	     ========================================================================= */
106	  .phone { --pad: 12px; background: var(--ground); border: 1.5px solid var(--wire-line); border-radius: 22px; padding: 10px; width: 100%; max-width: 260px; margin: 0 auto; aspect-ratio: 9 / 17.5; display: flex; flex-direction: column; overflow: hidden; }
107	  .screen { flex: 1; background: var(--panel); border-radius: 13px; border: 1px solid var(--wire-line); display: flex; flex-direction: column; overflow: hidden; position: relative; }
108	  .navbar { display: flex; align-items: center; gap: 8px; padding: 9px 12px; border-bottom: 1px solid var(--wire-line); font-family: var(--mono); font-size: 11px; color: var(--wire-ink); }
109	  .navbar .title { color: var(--ink); font-weight: 600; }
110	  .navbar .back::before { content: "\2039"; font-size: 15px; }
111	  .navbar .spacer { flex: 1; }
112	  .body { flex: 1; padding: var(--pad); display: flex; flex-direction: column; gap: 9px; overflow: hidden; }
113	  .body.center { justify-content: center; align-items: center; text-align: center; gap: 11px; }
114	
115	  /* Breadboard primitives ------------------------------------------------- */
116	  .w-mark { width: 46px; height: 46px; border-radius: 12px; background: var(--wire-fill-2); border: 1px solid var(--wire-line); }        /* app mark / icon */
117	  .w-h { height: 12px; border-radius: 4px; background: var(--wire-solid); }                                                             /* heading / label */
118	  .w-h.lg { height: 15px; width: 70%; }
119	  .w-t { height: 8px; border-radius: 4px; background: var(--wire-fill-2); }                                                             /* body text line */
120	  .w-t.w80 { width: 80%; } .w-t.w60 { width: 60%; } .w-t.w40 { width: 40%; }
121	  .center .w-h, .center .w-t { align-self: center; }
122	  .center .w-h.lg { width: 62%; } .center .w-t.w80 { width: 78%; } .center .w-t.w60 { width: 58%; }
123	
124	  .field { display: flex; flex-direction: column; gap: 4px; }                                                                          /* input field */
125	  .field .lbl { height: 7px; width: 34%; border-radius: 3px; background: var(--wire-fill-2); }
126	  .field .box { height: 26px; border-radius: 7px; border: 1px dashed var(--wire-line); background: var(--wire-fill); display: flex; align-items: center; padding: 0 8px; }  /* dashed = input */
127	  .field .box .ph { height: 7px; width: 55%; border-radius: 3px; background: var(--wire-line); opacity: 0.65; }
128	  .field .box.filled .ph { width: 40%; background: var(--wire-ink); opacity: 0.5; }
129	
130	  .btn { height: 30px; border-radius: 8px; background: var(--wire-solid); display: flex; align-items: center; justify-content: center; margin-top: 2px; }  /* solid = button */
131	  .btn.primary { background: var(--accent); }                                                                                          /* accent = primary/active */
132	  .btn .cap { height: 8px; width: 42%; border-radius: 3px; background: var(--panel); opacity: 0.9; }
133	  .btn.primary .cap { background: #fff; opacity: 0.95; }
134	
135	  .err { display: flex; align-items: center; gap: 6px; }                                                                               /* error row */
136	  .err .dot { width: 10px; height: 10px; border-radius: 50%; border: 1.5px solid var(--danger); flex: none; }
137	  .err .ln { height: 7px; width: 62%; border-radius: 3px; background: var(--danger); opacity: 0.55; }
138	
139	  .tabbar { display: flex; border-top: 1px solid var(--wire-line); padding: 7px 4px 5px; }                                             /* tab bar */
140	  .tabbar .tab { flex: 1; display: flex; flex-direction: column; align-items: center; gap: 4px; }
141	  .tabbar .tab .ic { width: 16px; height: 16px; border-radius: 5px; background: var(--wire-fill-2); border: 1px solid var(--wire-line); }
142	  .tabbar .tab .tl { height: 6px; width: 60%; border-radius: 3px; background: var(--wire-fill-2); }
143	  .tabbar .tab.active .ic { background: var(--accent); border-color: var(--accent); }
144	  .tabbar .tab.active .tl { background: var(--accent); }
145	
146	  .group { display: flex; flex-direction: column; gap: 6px; }                                                                          /* settings / list group */
147	  .group .gh { height: 8px; width: 30%; border-radius: 3px; background: var(--wire-solid); margin-left: 2px; }
148	  .rows { border: 1px solid var(--wire-line); border-radius: 10px; overflow: hidden; background: var(--wire-fill); }
149	  .row { display: flex; align-items: center; gap: 8px; padding: 9px 10px; border-bottom: 1px solid var(--wire-line); }
150	  .row:last-child { border-bottom: 0; }
151	  .row .av { width: 20px; height: 20px; border-radius: 50%; background: var(--wire-fill-2); border: 1px solid var(--wire-line); flex: none; }
152	  .row .ic { width: 16px; height: 16px; border-radius: 4px; background: var(--wire-fill-2); border: 1px solid var(--wire-line); flex: none; }
153	  .row .col { display: flex; flex-direction: column; gap: 4px; flex: 1; }
154	  .row .col .a { height: 7px; width: 60%; border-radius: 3px; background: var(--wire-solid); }
155	  .row .col .b { height: 6px; width: 44%; border-radius: 3px; background: var(--wire-fill-2); }
156	  .row.danger .lbl { height: 8px; width: 34%; border-radius: 3px; background: var(--danger); opacity: 0.6; }                            /* danger = destructive */
157	
158	  .modal-scrim { position: absolute; inset: 0; background: color-mix(in srgb, var(--ink) 32%, transparent); }                          /* modal sheet */
159	  .sheet { position: absolute; left: 0; right: 0; bottom: 0; background: var(--panel); border-top-left-radius: 16px; border-top-right-radius: 16px; border: 1px solid var(--wire-line); border-bottom: 0; padding: 8px 12px 12px; display: flex; flex-direction: column; gap: 8px; }
160	  .grabber { width: 34px; height: 4px; border-radius: 2px; background: var(--wire-line); align-self: center; margin-bottom: 2px; }
161	  .sheet-head { display: flex; align-items: center; justify-content: space-between; font-family: var(--mono); font-size: 10px; color: var(--wire-ink); }
162	  .sheet-head .t { color: var(--ink); font-weight: 600; font-size: 11px; }
163	  .dim { opacity: 0.4; }
164	  .inline-card { border: 1px solid var(--wire-line); border-radius: 11px; background: var(--wire-fill); padding: 10px; display: flex; flex-direction: column; gap: 8px; width: 100%; }
165	
166	  /* Breadboard (words) — places, affordances, connection lines; no pixels. */
167	  .breadboard { display: flex; flex-direction: column; gap: 4px; font-family: var(--mono); font-size: 11px; width: 100%; }
168	  .breadboard .place { border: 1px solid var(--wire-line); border-radius: 8px; background: var(--wire-fill); padding: 7px 9px; display: flex; flex-direction: column; gap: 4px; }
169	  .breadboard .place-name { color: var(--ink); font-weight: 600; text-decoration: underline; text-underline-offset: 2px; }  /* underlined = a place */
170	  .breadboard .afford { color: var(--wire-ink); }                                                                          /* [ affordances ] a user acts on */
171	  .breadboard .conn { color: var(--wire-ink); padding-left: 9px; }                                                         /* connection line to the next place */
172	  .breadboard .conn::before { content: "\2193  "; }                                                                        /* ↓ primary connection */
173	  .breadboard .conn.alt { border-left: 2px dashed var(--wire-line); margin-left: 3px; padding-left: 6px; font-style: italic; }  /* dashed = alternative / edge path */
174	  .breadboard .conn.alt::before { content: "\21B3  "; }                                                                    /* ↳ branch */
175	
176	  /* Wireflow — mini screens joined by control-rooted arrows. */
177	  .wireflow { display: flex; align-items: center; flex-wrap: wrap; gap: 6px; width: 100%; }
178	  .flowarrow { position: relative; flex: none; width: 52px; height: 22px; }                                               /* solid = primary path */
179	  .flowarrow::before { content: ""; position: absolute; left: 2px; right: 8px; top: 10px; border-top: 2px solid var(--wire-line); }
180	  .flowarrow::after { content: ""; position: absolute; right: 6px; top: 5px; width: 7px; height: 7px; border-top: 2px solid var(--wire-line); border-right: 2px solid var(--wire-line); transform: rotate(45deg); }
181	  .flowarrow.alt::before { border-top-style: dashed; }                                                                     /* dashed = alternative / edge path */
182	  .flowarrow .lbl { position: absolute; left: 0; right: 0; top: -6px; text-align: center; font-family: var(--mono); font-size: 8px; color: var(--wire-ink); }  /* the control that triggers it */
183	
184	  /* Annotation layer — reserved --anno color, used nowhere else. */
185	  .anno-wrap { display: flex; gap: 12px; align-items: flex-start; width: 100%; }
186	  .anno-notes { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 8px; flex: 1; }
187	  .anno { display: flex; gap: 7px; align-items: flex-start; }
188	  .anno-mark { flex: none; width: 16px; height: 16px; border-radius: 50%; border: 1.5px solid var(--anno); color: var(--anno); font-family: var(--mono); font-size: 9px; font-weight: 600; display: inline-flex; align-items: center; justify-content: center; }
189	  .anno-note { font-size: 11px; color: var(--anno); line-height: 1.42; }
190	  .anno-mark.pin { position: absolute; z-index: 2; background: var(--panel); }                                            /* leader marker pinned onto a region */
191	
192	  /* Legend: name every primitive so a reviewer can read the breadboard. */
193	  .legend { display: flex; flex-wrap: wrap; gap: 14px 22px; margin-top: 16px; font-size: 13px; color: var(--ink-soft); }
194	  .legend span { display: inline-flex; align-items: center; gap: 7px; }
195	  .sw { width: 26px; height: 15px; border-radius: 4px; border: 1px solid var(--wire-line); }
196	  .sw.solid { background: var(--wire-solid); } .sw.dashed { background: var(--wire-fill); border-style: dashed; }
197	  .sw.accent { background: var(--accent); border-color: var(--accent); } .sw.danger { background: transparent; border-color: var(--danger); }
198	  .sw.anno { background: transparent; border-color: var(--anno); }
199	  /* Component-library layout: flexbox so cards grow to fill each row. */
200	  .el-grid { display: flex; flex-wrap: wrap; gap: 14px; }
201	  .el-grid > .el-card { flex: 1 1 240px; }
202	  .el-card { background: var(--panel); border: 1px solid var(--line); border-radius: 12px; padding: 12px; display: flex; flex-direction: column; gap: 10px; }
203	  .el-tag { font-family: var(--mono); font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-soft); }
204	  .el-stage { flex: 1; display: flex; align-items: center; justify-content: center; min-height: 54px; padding: 10px; background: var(--wire-fill); border: 1px solid var(--wire-line); border-radius: 8px; }
205	  .el-stage > .w100 { width: 100%; }
206	  .el-card.wide { flex: 2 1 500px; } .el-card.wide3 { flex: 3 1 760px; }
207	  .el-sub { font-family: var(--mono); font-size: 11px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--ink-soft); margin: 26px 0 12px; }
208	  /* ---- wireframe component specimens (breadboard greys) ---- */
209	  .wc-lbl { height: 7px; border-radius: 3px; background: var(--wire-fill-2); }
210	  .wc-solid { height: 8px; border-radius: 3px; background: var(--wire-solid); }
211	  .wc-check { width: 18px; height: 18px; border-radius: 5px; border: 1.5px solid var(--wire-line); background: var(--wire-fill); position: relative; flex: none; }
212	  .wc-check.on { background: var(--accent); border-color: var(--accent); }
213	  .wc-check.on::after { content: ""; position: absolute; left: 5px; top: 2px; width: 4px; height: 8px; border: solid var(--panel); border-width: 0 2px 2px 0; transform: rotate(45deg); }
214	  .wc-radio { width: 18px; height: 18px; border-radius: 50%; border: 1.5px solid var(--wire-line); background: var(--wire-fill); display: inline-flex; align-items: center; justify-content: center; flex: none; }
215	  .wc-radio.on { border-color: var(--accent); }
216	  .wc-radio.on::after { content: ""; width: 9px; height: 9px; border-radius: 50%; background: var(--accent); }
217	  .wc-opt { display: flex; align-items: center; gap: 8px; } .wc-opt .wc-lbl { width: 60%; }
218	  .wc-switch { width: 34px; height: 20px; border-radius: 999px; background: var(--wire-line); position: relative; flex: none; }
219	  .wc-switch.on { background: var(--accent); }
220	  .wc-switch::after { content: ""; position: absolute; top: 2px; left: 2px; width: 16px; height: 16px; border-radius: 50%; background: var(--panel); }
221	  .wc-switch.on::after { left: 16px; }
222	  .wc-slider { height: 18px; display: flex; align-items: center; }
223	  .wc-slider .track { height: 4px; border-radius: 2px; background: var(--wire-line); flex: 1; position: relative; }
224	  .wc-slider .fill { position: absolute; left: 0; top: 0; height: 100%; width: 55%; background: var(--accent); border-radius: 2px; }
225	  .wc-slider .thumb { position: absolute; left: 55%; top: 50%; transform: translate(-50%, -50%); width: 14px; height: 14px; border-radius: 50%; background: var(--panel); border: 1.5px solid var(--accent); }
226	  .wc-prog { height: 6px; border-radius: 3px; background: var(--wire-line); overflow: hidden; width: 100%; }
227	  .wc-prog .fill { height: 100%; width: 62%; background: var(--accent); }
228	  .wc-av { width: 32px; height: 32px; border-radius: 50%; background: var(--wire-fill-2); border: 1px solid var(--wire-line); flex: none; }
229	  .wc-avstack { display: flex; } .wc-avstack .wc-av + .wc-av { margin-left: -9px; box-shadow: 0 0 0 2px var(--panel); }
230	  .wc-badge { display: inline-flex; align-items: center; justify-content: center; height: 20px; min-width: 34px; padding: 0 10px; border-radius: 999px; background: var(--wire-solid); }
231	  .wc-badge .t { height: 6px; width: 22px; border-radius: 3px; background: var(--wire-ink); opacity: 0.7; }
232	  .wc-badge.count { min-width: 20px; width: 20px; height: 20px; padding: 0; } .wc-badge.count .t { width: 8px; }
233	  .wc-div { height: 1px; background: var(--wire-line); width: 100%; }
