1	#!/usr/bin/env node
2	// check-wireframe.mjs — output validator for low-fidelity wireframe pages.
3	//
4	// a wireframe produced from wireframe-kit.html must satisfy two of the skill's
5	// MUST rules that are mechanically checkable: it must stay self-contained (no
6	// external resource fetch, so it renders offline and can never leak a request),
7	// and it must carry no leftover template placeholders (`FILL:` markers or
8	// `lorem ipsum` filler). this script checks a filled page for both, so an
9	// author can gate a wireframe before presenting it.
10	//
11	// it is dependency-light (Node standard library only). it intentionally does
12	// not judge hierarchy, grouping, or grayscale discipline — those need a human
13	// eye and the research-grounded rules in the skill; this is a floor, not a
14	// substitute for the review.
15	//
16	// usage:
17	//   node check-wireframe.mjs <file.html> [<file.html> ...]
18	//
19	// exit codes:
20	//   0  every checked file passed
21	//   1  one or more files failed (each failure is listed per file), or a file
22	//      could not be read
23	//   2  bad invocation (no file arguments)
24	//
25	// note: the un-filled kit (wireframe-kit.html) deliberately contains `FILL:`
26	// markers, so it is meant to fail here. run this on your filled copy.
27	
28	import { readFile } from "node:fs/promises";
29	
30	/**
31	 * true when a resource URL points off the page — an absolute http(s) URL or a
32	 * protocol-relative `//host` reference. in-page anchors (`#…`), inline `data:`
33	 * payloads, and relative paths are self-contained and pass.
34	 * @param {string} url
35	 * @returns {boolean}
36	 */
37	function isExternalUrl(url) {
38	  const trimmed = url.trim();
39	  return /^https?:\/\//i.test(trimmed) || /^\/\//.test(trimmed);
40	}
41	
42	/** turn a byte offset into a 1-indexed line number for reporting. */
43	function lineOf(text, index) {
44	  let line = 1;
45	  for (let i = 0; i < index && i < text.length; i += 1) {
46	    if (text[i] === "\n") line += 1;
47	  }
48	  return line;
49	}
50	
51	/**
52	 * collect every external-fetch failure in the page. covers the four ways a
53	 * self-contained page can be broken: `src`/`srcset` attributes, `<link href>`,
54	 * CSS `@import`, and CSS `url(...)`. plain `<a href>` is a navigation link, not
55	 * a fetch, so it is deliberately not scanned.
56	 * @param {string} text
57	 * @returns {string[]} human-readable failure lines
58	 */
59	function externalFetchFailures(text) {
60	  const failures = [];
61	  const seen = new Set();
62	  const flag = (kind, url, index) => {
63	    const key = `${kind}:${url}:${index}`;
64	    if (seen.has(key)) return;
65	    seen.add(key);
66	    failures.push(`self-containment: external ${kind} at line ${lineOf(text, index)} — ${url}`);
67	  };
68	
69	  // src="…" (single value) — <img>, <script>, <iframe>, <source>, etc.
70	  for (const m of text.matchAll(/\bsrc\s*=\s*["']([^"']+)["']/gi)) {
71	    if (isExternalUrl(m[1])) flag("src", m[1], m.index);
72	  }
73	  // srcset="url 1x, url 2x" — each candidate's URL is the token before any descriptor.
74	  for (const m of text.matchAll(/\bsrcset\s*=\s*["']([^"']+)["']/gi)) {
75	    for (const candidate of m[1].split(",")) {
76	      const url = candidate.trim().split(/\s+/)[0];
77	      if (url && isExternalUrl(url)) flag("srcset", url, m.index);
78	    }
79	  }
80	  // <link href="…"> — a stylesheet/font/icon fetch (unlike <a href>).
81	  for (const m of text.matchAll(/<link\b[^>]*?\bhref\s*=\s*["']([^"']+)["'][^>]*>/gi)) {
82	    if (isExternalUrl(m[1])) flag("link href", m[1], m.index);
83	  }
84	  // @import "…" or @import url(…)
85	  for (const m of text.matchAll(/@import\s+(?:url\(\s*)?["']?([^"')]+)/gi)) {
86	    if (isExternalUrl(m[1])) flag("@import", m[1], m.index);
87	  }
88	  // url(…) in CSS (inline styles or <style>) — fonts, background images, etc.
89	  for (const m of text.matchAll(/url\(\s*["']?([^"')]+)["']?\s*\)/gi)) {
90	    if (isExternalUrl(m[1])) flag("url()", m[1], m.index);
91	  }
92	
93	  return failures;
94	}
95	
96	/**
97	 * collect leftover-placeholder failures: unfilled `FILL:` markers and any
98	 * `lorem ipsum` filler text (which the skill forbids in favor of real content).
99	 * @param {string} text
100	 * @returns {string[]} human-readable failure lines
101	 */
102	function placeholderFailures(text) {
103	  const failures = [];
104	  for (const m of text.matchAll(/FILL:/g)) {
105	    failures.push(`placeholder: leftover "FILL:" marker at line ${lineOf(text, m.index)}`);
106	  }
107	  for (const m of text.matchAll(/lorem ipsum/gi)) {
108	    failures.push(`placeholder: "lorem ipsum" filler at line ${lineOf(text, m.index)}`);
109	  }
110	  return failures;
111	}
112	
113	/** run every check for one file; returns failure strings (empty when clean). */
114	async function checkFile(path) {
115	  let text;
116	  try {
117	    text = await readFile(path, "utf8");
118	  } catch (error) {
119	    return [`unreadable: ${error.message}`];
120	  }
121	  return [...externalFetchFailures(text), ...placeholderFailures(text)];
122	}
123	
